/**
 * @distilled.cloud/unifi-network -- UniFi Network SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from Ubiquiti's OpenAPI spec
 * (https://developer.ui.com/network/v11.0.97/openapi.json), mirrored at
 * `specs/spec-mirror-unifi-network/specs/openapi.json`. Everything else in
 * this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Effect from "effect/Effect";
 * import * as Layer from "effect/Layer";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as UniFiNetwork from "@distilled.cloud/unifi-network";
 *
 * const program = UniFiNetwork.getSiteOverviewPage({});
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(
 *       FetchHttpClient.layer,
 *       UniFiNetwork.CredentialsFromEnv,
 *       UniFiNetwork.UniFiNetworkProtocol,
 *     ),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  UniFiNetworkProtocol,
  type UniFiNetworkOpError,
  type UniFiNetworkOpContext,
} from "./protocol.ts";
export { paginateOffset } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations, their request/response types and typed errors are importable
// straight off the package root.
export * from "./services/unifiNetwork.ts";
